#!/usr/bin/env sh
set -eu
RUN="${YUZHOU_MIGRATION_RUN_ID:-}";DB="${YUZHOU_TARGET_DATABASE:-}";PG="${YUZHOU_POSTGRES_CONTAINER:-jinhu-smart-park-postgres}";[ "${ALLOW_YUZHOU_MIGRATION:-no}" = yes ]||exit 2;printf %s "$DB"|grep -Eq '^jinhu_hr_migration_lab_'||exit 2
docker exec -i "$PG" psql -X -v ON_ERROR_STOP=1 -U jinhu -d "$DB" -v run="$RUN" <<'SQL'
BEGIN;SELECT set_config('yz.run',:'run',true);DO $$BEGIN IF NOT EXISTS(SELECT 1 FROM migration_batch WHERE run_id=current_setting('yz.run') AND status='succeeded')THEN RAISE EXCEPTION 'succeeded batch not found';END IF;END$$;DELETE FROM hr_contract_change x USING legacy_record_map m,migration_batch b WHERE m.batch_id=b.id AND b.run_id=:'run' AND m.target_table='hr_contract_change' AND m.is_active AND x.id=m.target_id;DELETE FROM hr_contract x USING legacy_record_map m,migration_batch b WHERE m.batch_id=b.id AND b.run_id=:'run' AND m.target_table='hr_contract' AND m.is_active AND x.id=m.target_id;DELETE FROM hr_contract_type x USING legacy_record_map m,migration_batch b WHERE m.batch_id=b.id AND b.run_id=:'run' AND m.target_table='hr_contract_type' AND m.is_active AND x.id=m.target_id;UPDATE legacy_record_map SET is_active=false WHERE batch_id=(SELECT id FROM migration_batch WHERE run_id=:'run');UPDATE migration_batch SET status='rolled_back',phase='rollback',finished_at=now()WHERE run_id=:'run';COMMIT;
SQL
